use super::*;
fn id()->EnumAssetId{EnumAssetId::parse("0123456789abcdef0123456789abcdef").unwrap()}
fn member(n:u128)->EnumMemberId{EnumMemberId::parse(&format!("{n:032x}")).unwrap()}
fn fresh()->EnumAsset{EnumAsset::new(id(),"State".into()).unwrap()}
fn add(value:&mut EnumAsset,n:u128,label:&str)->EnumMemberId{let id=member(n);value.prepare(EnumCommand::Add{member:id,display_name:label.into(),description:String::new()}).unwrap().commit(value).unwrap();id}
#[test]fn uuid_enum_empty_has_identity_without_visible_max(){let v=fresh();assert_eq!(v.id(),id());assert!(v.members().is_empty());}
#[test]fn uuid_enum_canonical_nonzero_ids(){for raw in ["00000000000000000000000000000000","0123456789ABCDEF0123456789abcdef","0000000000000001","../0123456789abcdef0123456789abcdef"]{assert!(EnumMemberId::parse(raw).is_err());assert!(EnumAssetId::parse(raw).is_err());}assert_eq!(member(1).to_hex(),"00000000000000000000000000000001");}
#[test]fn uuid_enum_dropped_prepare_is_read_only(){let v=fresh();let before=v.clone();drop(v.prepare(EnumCommand::Add{member:member(1),display_name:"Waiting".into(),description:String::new()}).unwrap());assert_eq!(v,before);}
#[test]fn uuid_enum_opaque_identity_is_not_ordinal(){let mut v=fresh();let a=add(&mut v,u128::MAX,"A");let b=add(&mut v,1,"B");assert_eq!(v.ordinal(v.value(a).unwrap()),Ok(0));assert_eq!(v.ordinal(v.value(b).unwrap()),Ok(1));}
#[test]fn uuid_enum_display_counter_does_not_constrain_id(){let mut v=fresh();add(&mut v,u128::MAX,"A");let mut p=v.parts().clone();p.next_member_id=1;assert!(EnumAsset::from_parts(p).is_ok());}
#[test]fn uuid_enum_duplicate_name_id_and_bad_label_are_atomic(){let mut v=fresh();add(&mut v,8,"Same");let before=v.clone();for(id,label)in [(member(8),"Other"),(member(9),"Same"),(member(9),"  "),(member(9),"(INVALID)"),(member(9),"a\n")]{assert!(v.prepare(EnumCommand::Add{member:id,display_name:label.into(),description:String::new()}).is_err());assert_eq!(v,before);}}
#[test]fn uuid_enum_reorder_preserves_typed_value(){let mut v=fresh();let a=add(&mut v,1,"A");let b=add(&mut v,2,"B");let r=v.value(a).unwrap();v.prepare(EnumCommand::Move{member:a,index:1}).unwrap().commit(&mut v).unwrap();assert_eq!(v.members()[0].id,b);assert_eq!(v.ordinal(r),Ok(1));}
#[test]fn uuid_enum_remove_rejects_reference_and_plain_id_reuse(){let mut v=fresh();let a=add(&mut v,1,"A");let r=v.value(a).unwrap();v.prepare(EnumCommand::Remove(a)).unwrap().commit(&mut v).unwrap();assert!(v.ordinal(r).is_err());assert!(v.prepare(EnumCommand::Add{member:a,display_name:"Unrelated".into(),description:String::new()}).is_err());}
#[test]fn uuid_enum_exact_undo_redo_restores_member(){let mut v=fresh();let a=add(&mut v,1,"A");let before=v.clone();let r=v.value(a).unwrap();let remove=v.prepare(EnumCommand::Remove(a)).unwrap();remove.commit(&mut v).unwrap();let removed=v.clone();let undo=remove.undo(&v).unwrap();undo.commit(&mut v).unwrap();assert_eq!(v,before);assert_eq!(v.ordinal(r),Ok(0));undo.undo(&v).unwrap().commit(&mut v).unwrap();assert_eq!(v,removed);}
#[test]fn uuid_enum_undo_add_and_branch_use_fresh_supplied_id(){let mut v=fresh();let baseline=v.clone();let old=member(1);let t=v.prepare(EnumCommand::Add{member:old,display_name:"Old".into(),description:String::new()}).unwrap();t.commit(&mut v).unwrap();t.undo(&v).unwrap().commit(&mut v).unwrap();assert_eq!(v,baseline);let new=add(&mut v,2,"New");assert_ne!(old,new);assert!(v.ordinal(EnumValue{asset:id(),member:old}).is_err());}
#[test]fn uuid_enum_discard_then_fresh_id_never_retargets_reference(){let mut v=fresh();let saved=v.clone();let old=add(&mut v,1,"Old");let r=v.value(old).unwrap();v=saved;let new=add(&mut v,2,"New");assert_ne!(old,new);assert!(v.ordinal(r).is_err());}
#[test]fn uuid_enum_commit_and_undo_reject_foreign_baseline(){let mut v=fresh();let t=v.prepare(EnumCommand::Bitflags(true)).unwrap();v.prepare(EnumCommand::DescribeAsset("Other".into())).unwrap().commit(&mut v).unwrap();assert!(t.commit(&mut v).is_err());assert!(t.undo(&v).is_err());}
#[test]fn uuid_enum_import_rejects_foreign_asset_or_retired_resurrection(){let mut v=fresh();let a=add(&mut v,1,"A");let original=v.clone();v.prepare(EnumCommand::Remove(a)).unwrap().commit(&mut v).unwrap();assert!(v.prepare_import(original).is_err());let foreign=v.duplicate(EnumAssetId::parse("ffffffffffffffffffffffffffffffff").unwrap(),"Copy".into()).unwrap();assert!(v.prepare_import(foreign).is_err());}
#[test]fn uuid_enum_import_reports_removed_nominal_values(){let mut v=fresh();let a=add(&mut v,1,"A");add(&mut v,2,"B");let old=v.value(a).unwrap();let mut p=v.parts().clone();p.members.retain(|m|m.id!=a);let t=v.prepare_import(EnumAsset::from_parts(p).unwrap()).unwrap();assert_eq!(t.removed_values(),&[old]);t.commit(&mut v).unwrap();assert!(v.parts().retired.contains(&a));}
#[test]fn uuid_enum_duplicate_has_new_asset_identity(){let mut v=fresh();let a=add(&mut v,1,"A");let old=v.value(a).unwrap();let copy=v.duplicate(EnumAssetId::parse("ffffffffffffffffffffffffffffffff").unwrap(),"Copy".into()).unwrap();assert!(copy.ordinal(old).is_err());assert_eq!(copy.members()[0].id,a);}
#[test]fn uuid_enum_malformed_models_reject_duplicate_zero_and_live_retired(){let mut v=fresh();let a=add(&mut v,1,"A");let mut p=v.parts().clone();p.members.push(p.members[0].clone());assert!(EnumAsset::from_parts(p).is_err());let mut p=v.parts().clone();p.retired.insert(a);assert!(EnumAsset::from_parts(p).is_err());let mut p=v.parts().clone();p.members[0].id=EnumMemberId(0);assert!(EnumAsset::from_parts(p).is_err());}
#[test]fn uuid_enum_byte_domain_bound_is_atomic(){let mut v=fresh();for n in 1..=ENUM_MAX_MEMBERS{add(&mut v,n as u128,&format!("Entry{n}"));}let before=v.clone();assert!(v.prepare(EnumCommand::Add{member:member(256),display_name:"Extra".into(),description:String::new()}).is_err());assert_eq!(v,before);}
#[test]fn uuid_enum_unicode_description_inverse_and_flags_keep_members(){let mut v=fresh();let a=add(&mut v,1,"État é🌟");let before=v.clone();let t=v.prepare(EnumCommand::DescribeMember{member:a,description:"First\nSecond é🌟".into()}).unwrap();t.commit(&mut v).unwrap();t.undo(&v).unwrap().commit(&mut v).unwrap();assert_eq!(v,before);v.prepare(EnumCommand::Bitflags(true)).unwrap().commit(&mut v).unwrap();assert!(v.parts().bitflags);assert_eq!(v.members()[0].display_name,"État é🌟");}
